  const explanation = $('#explain-input').value.trim();
  if (explanation.replace(/\s/g, '').length < 12) {
    $('#explain-error').classList.remove('hidden');
    $('#explain-input').focus();
    return;
  }
  const correctAnswer = currentQuestions[questionIndex].answers.find(answer => answer[1]);
