211: function playTone(correct) {
212:   if (!soundOn) return;
213:   try {
214:     audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
215:     const oscillator = audioContext.createOscillator();
216:     const gain = audioContext.createGain();
217:     oscillator.type = 'sine';
218:     oscillator.frequency.value = correct ? 660 : 245;
219:     gain.gain.setValueAtTime(.055, audioContext.currentTime);
220:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + .17);
221:     oscillator.connect(gain); gain.connect(audioContext.destination);
222:     oscillator.start(); oscillator.stop(audioContext.currentTime + .18);
223:   } catch (_) { /* Audio is an optional flourish. */ }
224: }
225: function shuffle(items) {
226:   const result = [...items];
227:   for (let i = result.length - 1; i > 0; i--) {
228:     const j = Math.floor(Math.random() * (i + 1));
229:     [result[i], result[j]] = [result[j], result[i]];
230:   }
231:   return result;
232: }
233: function renderQuestion() {
234:   const question = currentQuestions[questionIndex];
235:   hasAnswered = false;
236:   reviewingQuestion = false;
237:   currentOptions = shuffle(question.answers);
238:   $('#chapter-name').textContent = chapter.name;
239:   $('#chapter-index').textContent = `CHAPTER ${String(chapters.indexOf(chapter) + 1).padStart(2, '0')}`;
240:   $('#crumb-chapter').textContent = chapter.short;
