244:   $('#progress-count').textContent = `${String(questionIndex + 1).padStart(2, '0')} / ${String(currentQuestions.length).padStart(2, '0')}`;
245:   $('#progress-fill').style.width = `${(questionIndex / currentQuestions.length) * 100}%`;
246:   $('#progress-dots').innerHTML = currentQuestions.map((_, i) => `<span class="${i < questionIndex ? 'done' : ''}"></span>`).join('');
247:   $('#streak-count').textContent = streak;
248:   $('#score-count').textContent = score;
